css:
.header {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    padding-bottom: 4px;
}

.info {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    padding-bottom: 2px;

}

html:
{% set company = frappe.db.get_value("Company", doc.company, ["*"], as_dict = true) %}
{% set letter_head = frappe.db.get_value("Letter Head", company.default_letter_head, ["image"], as_dict=true) %}
{% set links = frappe.get_all('Dynamic Link', filters={'link_doctype': 'Company', 'link_name': doc.company, 'parenttype': 'Address'}, fields=['parent']) %}
{% if links %}
{% set address = frappe.db.get_value("Address", links[0].parent, ["*"], as_dict=true) %}
{% endif %}

{% set patient = frappe.db.get_value("Patient", doc.patient, ["*"], as_dict=true) %}
{% set practitioner = frappe.db.get_value("Healthcare Practitioner", doc.referring_practitioner, ["*"], as_dict=true) %}
{% set dob = frappe.utils.getdate(patient.dob) %} {# Replace with actual DOB #}
{% set today = frappe.utils.nowdate() %}
{% set birth_date = frappe.utils.getdate(dob) %}
{% set current_date = frappe.utils.getdate(today) %}
{% set age = current_date.year - birth_date.year - ((current_date.month, current_date.day) < (birth_date.month, birth_date.day)) %}

{% macro header() %}
<div class="header">
    <div class="">
        <img src="{{letter_head.image}}"  style="width:100px; margin-bottom:32px;" />

    </div>
    <div style="text-align: center">
        <h1>Premium Care</h1>
        <h2>Receipt</h2>
        <p>{{doc.name}}</p>
    </div>

    <div style="text-align: right;">
        {% if address.address_title %}
            <p style="font-weight: bold; font-size: large;">{{address.address_title}}<p/>
        {% endif %}
        {% if address.address_line1 %}
            <p>{{address.address_line1}}</p>
        {% endif %}
        {% if address.city %}
            <p>{{address.city}}</p>
        {% endif %}
        {% if address.pincode %}
            <p>{{address.pincode}}</p>
        {% endif %}
        <p>Tel: 4908128</p>
        <p>BRN: C22188669</p>
        <p>Email: info@premiumcareclinic.mu</p>
    </div>

</div>
{% endmacro %}

{% macro info() %}
<div class="info">
    <div class="col">
        <section class="patient-info">

            <p><strong>Name:</strong> {{ doc.patient_name }}</p>
            <p><strong>Patient HIS:</strong> {{ doc.patient }}</p>

            <p>
            {% if patient.dob %}
                <strong>D.O.B:</strong> {{ frappe.utils.formatdate(patient.dob) }}  ({{age}} yrs) 
            {% endif %}
            ({{ "M" if  patient.sex == "Male" else "F"  }})
            </p>
            {% if patient.address %}
            <p><strong>Address:</strong> </p>
            <p style="white-space-collapse: preserve;">{{ patient.address }}</p>
            {% endif %}
            <p><strong>Tel:</strong> {{ patient.mobile }}</p>
            {%if patient.uid %}
                <p><strong>NID:</strong> {{ patient.uid }}</p>
            {% endif %}
        </section>
    </div>
    <div class="col">
        {% if doc.referring_practitioner %}
            <section class="patient-info">
                <div style="height: 45px;"></div>
                <p><strong>Referring Practitioner:</strong> {{ doc.referring_practitioner }}</p>
                <p>{{frappe.format_date(doc.creation)}}</p>
            </section>
        {% endif %}

    </div>
</div>
{% endmacro %}

{% if doc.status == "Paid" %}
<div style="font-family: Arial, sans-serif; margin: 20px; padding: 10px;">
    {{header() }}
    <hr style="margin: 20px 0;">
    <p><strong>Date:</strong> {{ frappe.format_date(doc.posting_date) }}</p>
    <p><strong>Received From:</strong> {{ doc.customer_name or doc.party_name }}</p>
    <p><strong>The sum of Rs:</strong> {{ frappe.utils.fmt_money(doc.grand_total or doc.paid_amount) }}</p>
    <p><strong>(in words):</strong> {{ frappe.utils.money_in_words(doc.grand_total or doc.paid_amount) }}</p>
    <p><strong>Being payment for:</strong> {{ doc.remarks or "Service/Product Details" }}</p>
    <br><br>
    <p class="text-right"><strong>Name:</strong> ............................................................</p>
    <p><strong>Signature:</strong> .....................................................</p>
</div>

{% endif %}
